def snapshot(root,excluded_dirs=(),excluded_files=()):
    root=Path(root);entries={}
    def visit(p):
        rel=str(p.relative_to(root));a=p.lstat();mode=stat.S_IMODE(a.st_mode)
        if rel in excluded_dirs:
            assert stat.S_ISDIR(a.st_mode),'output root is not real directory: '+str(p)
            return
        if rel in excluded_files:
            assert stat.S_ISREG(a.st_mode),'mutable record is not regular file: '+str(p)
            return
        if stat.S_ISDIR(a.st_mode):
            entries[rel]={'kind':'directory','mode':mode}
            for q in sorted(p.iterdir()):visit(q)
        else:
            assert stat.S_ISREG(a.st_mode),'link or special immutable input: '+str(p)
            raw=p.read_bytes()
            entries[rel]={'kind':'file','mode':mode,'bytes':a.st_size,'sha256':hashlib.sha256(raw).hexdigest()}
        b=p.lstat()
        fields=lambda s:(s.st_dev,s.st_ino,s.st_mode,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
        assert fields(a)==fields(b),'input changed during readback: '+str(p)
    visit(root);return entries

