def load(path):
    return json.loads(Path(path).read_text())


def fields(row):
    return (row.st_dev, row.st_ino, row.st_mode, row.st_nlink, row.st_size,
            row.st_mtime_ns, row.st_ctime_ns)


def pin(path):
    path = Path(path)
    before = path.lstat()
    assert stat.S_ISREG(before.st_mode) and not path.is_symlink(), str(path)
    with path.open('rb') as stream:
        digest = hashlib.file_digest(stream, 'sha256').hexdigest()
    after = path.lstat()
    assert fields(before) == fields(after), ('Changed during read', str(path))
    return {'sha256': digest, 'bytes': after.st_size, 'mode': stat.S_IMODE(after.st_mode)}


def pinned(path):
    return {'path': str(Path(path)), **pin(path)}


def matched(row):
    assert set(row) == {'path', 'sha256', 'bytes', 'mode'}, row
    path = Path(row['path'])
    assert path.is_absolute() and pinned(path) == row, str(path)
    return path


def save(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write('\n'); stream.flush(); os.fsync(stream.fileno())
    os.chmod(path, 0o644)
    return pinned(path)


def clone(origin, destination):
    origin, destination = Path(origin), Path(destination)
    before = pin(origin)
    destination.parent.mkdir(parents=True, exist_ok=True)
    with destination.open('xb') as stream:
        stream.write(origin.read_bytes()); stream.flush(); os.fsync(stream.fileno())
    os.chmod(destination, before['mode'])
    assert pin(origin) == before == pin(destination), str(origin)


def under(name, roots):
    return any(name == root or name.startswith(root + '/') for root in roots)


def snapshot(root, excluded=(), allow_links=False):
    root = Path(root)
    rows = {}
    def visit(path):
        name = path.relative_to(root).as_posix()
        before = path.lstat()
        mode = stat.S_IMODE(before.st_mode)
        if under(name, excluded):
            assert stat.S_ISDIR(before.st_mode) and not path.is_symlink(), name
            return
        if stat.S_ISDIR(before.st_mode):
            rows[name] = {'kind': 'directory', 'mode': mode}
            for child in sorted(path.iterdir()):
                visit(child)
        elif stat.S_ISREG(before.st_mode):
            rows[name] = {'kind': 'file', **pin(path)}
        elif allow_links and stat.S_ISLNK(before.st_mode):
            rows[name] = {'kind': 'symlink', 'mode': mode, 'target': os.readlink(path)}
        else:
            raise RuntimeError('Unadmitted link/special input: ' + str(path))
        assert fields(before) == fields(path.lstat()), ('Changed during traversal', name)
    visit(root)
    return rows


