                               and '..' not in path.parts), name
        assert type(row['mode']) is int and 0 <= row['mode'] <= 0o7777, name
        if row['kind'] == 'file':
            assert set(row) == {'kind', 'mode', 'bytes', 'sha256'}, name
            assert type(row['bytes']) is int and row['bytes'] >= 0, name
            assert re.fullmatch('[0-9a-f]{64}', row['sha256']), name
        else:
            assert row['kind'] == 'directory' and set(row) == {'kind', 'mode'}, name
