        text = re.sub(r'--[^\n]*', '', Path(source, name).read_text())
        for clause in re.findall(r'\bwith\s+([^;]+);', text, flags=re.IGNORECASE):
            for imported in re.findall(r'"([^"]+)"', clause):
                if Path(imported).stem.lower() in ('sparklib', 'sparklib_common'):
                    assert imported.lower() in ('sparklib', 'sparklib.gpr', 'sparklib_common', 'sparklib_common.gpr')
                    imports.append({'project': name, 'import': imported})
    return imports


def check_dependency(root=D):
    root = Path(root)
    plan = load(root / 'dependency-inventory.json')
    assert plan['installed_root'] == str(INSTALLED) and plan['private_root'] == str(root / 'private-sparklib')
    assert plan['output_directories'] == list(DEPENDENCY_OUTPUTS)
    assert plan['entries'] == dependency_entries() == snapshot(root / 'private-sparklib', DEPENDENCY_OUTPUTS)
    assert plan['shared_output_inventory'] == shared_outputs(), 'Installed output drift; no rebaseline'
    assert plan['source_mode'] == 'full' and plan['compiler_mode'] == 'Production' and plan['library_kind'] == 'static'
    assert plan['proof_only_substitution'] is False and plan['GPR_TOOL_override'] is False
    return {'private_inputs': plan['entries'], 'shared_outputs_unchanged': True, 'acceptance': False}


def child_environment(root, environment):
    result = dict(environment)
    for key in DEPENDENCY_UNSET:
        assert result.get(key) is None, ('Unexpected project/mode override', key)
    inherited = load(Path(root) / 'inherited-protected-environment.json')
    assert result['GPR_PROJECT_PATH'] == inherited['GPR_PROJECT_PATH']
    result['GPR_PROJECT_PATH'] = str(Path(root) / 'private-sparklib/lib/gnat') + ':' + result['GPR_PROJECT_PATH']
    return result


def observer(root, name):
    path = Path(root) / (name + '.py')
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def check_additional_closure(root=D):
    root = Path(root)
    pc = load(root / 'proof-data-closure.json')
    assert observer(root, 'proof_data_inventory').observe(pc['spec']) == pc['inventory'], 'Proof DATA drift'
    tools = load(root / 'action-baseline.json')['tool_inventory']
    assert observer(root, 'proof_elf_inventory').observe(tools) == load(root / 'proof-elf-baseline.json'), 'ELF drift'
    return {'proof_data_and_elf_match': True, 'acceptance': False}


def check_current_inputs(root=D):
    root = Path(root)
    entries = snapshot(root / 'source', SOURCE_OUTPUTS)
    assert entries == load(root / 'selected-source-entries.json'), 'Full source kind/mode/hash/length/keyset drift'
    assert project_routing(root / 'source', entries) == load(root / 'source-binding-adaptation.json')['vendor_imports']
    return {'complete_source_entries': entries, 'dependency': check_dependency(root),
            'additional_closure': check_additional_closure(root), 'acceptance': False}


def retained_readback(root=D):
    try:
        return {'matches': True, 'actual': check_current_inputs(root), 'acceptance': False}
    except (OSError, AssertionError, RuntimeError, ValueError) as error:
        return {'matches': False, 'error': repr(error), 'acceptance': False}


def generated_outputs(root=D):
    root = Path(root)
    names = tuple('source/' + name for name in SOURCE_OUTPUTS) + tuple('private-sparklib/' + name for name in DEPENDENCY_OUTPUTS)
    return {name: snapshot(root / name, allow_links=True) if (root / name).exists() else None for name in names}


def closure_origin(name):
    return (F if name in ('proof-data-closure.json', 'proof-elf-baseline.json') else O24) / name


def check_closure_contract(documents):
    assert set(documents) == set(CLOSURE_FILES)
    inherited = {name: load(closure_origin(name)) for name in CLOSURE_FILES}
    old = inherited['tool-inventory-template.json']['tool_inventory_spec']
    new = documents['tool-inventory-template.json']['tool_inventory_spec']
    for key in ('roots', 'direct_paths', 'path_commands'):
        assert new[key] == old[key], ('Original tool discovery removed/reordered', key)
    assert set(new['effective_environment']) == set(old['effective_environment'])
    for key, value in old['effective_environment'].items():
        if key != 'PATH':
            assert new['effective_environment'][key] == value, ('Protected environment changed', key)
    for name in ('runtime-closure.json', 'proof-data-closure.json'):
        assert documents[name]['spec'] == inherited[name]['spec'], ('Closure discovery removed/changed', name)
    old_base, new_base = inherited['action-baseline.json'], documents['action-baseline.json']
    assert set(new_base['manager_environment']) == set(old_base['manager_environment'])
    assert new_base['source_files'] == old_base['source_files'], 'Source replacement is separately bound, not closure rebaseline'
    assert [row['original'] for row in documents['vendor-template.json']] == [row['original'] for row in inherited['vendor-template.json']]
    prefixes = ':'.join('/home/sicarii/opt/gnat/' + name + '/bin' for name in
                        ('gnat-aarch64-linux-16.1.0-1', 'gprbuild-aarch64-linux-26.0.0-1', 'gnatprove-aarch64-linux-16.1.0-1'))
    assert new['effective_environment']['PATH'] == prefixes + ':' + documents['launch-environment.json']['PATH']
    return inherited


def check_historical_acknowledgement(row):
    descriptor = load(matched(row))
    acknowledgement = load(matched(descriptor['acknowledgement']))
    assert acknowledgement['schema'] == 'lead-explicit-historical-identity-drift-acknowledgement-v1'
    approval = acknowledgement['operator_approval']
    matched({key: approval[key] for key in ('path', 'sha256', 'bytes', 'mode')})
    assert matched(descriptor['operator_approval']) == Path(approval['path'])
    paths = {str(INSTALLED / 'lib/gnat/sparklib_lib/libsparklib.a'),
             str(INSTALLED / 'lib/gnat/sparklib_obj/sparklib.lexch')}
    assert {item['path'] for item in acknowledgement['rows']} == set(descriptor['used']) == paths
    for item in acknowledgement['rows']:
        original_map = matched({key: item['historical_map'][key] for key in ('path', 'sha256', 'bytes', 'mode')})
        assert original_map.name == 'bound-inputs.json'
        assert item['historical_map']['key'] == 'historical_f7_v2_bound_inputs'
    assert len(acknowledgement['rows']) == 2 and descriptor['history_only'] is True
    assert descriptor['target_execution'] is False
    return descriptor
